package com.byawasaya.platform.storage;
import java.io.*; import java.security.MessageDigest; import java.util.*; import javax.imageio.ImageIO; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import com.byawasaya.platform.audit.AuditService; import com.byawasaya.platform.auth.TokenService; import com.byawasaya.platform.business.*;
@RestController public class StoreAssetController {
 private static final long MAX=5L*1024*1024; private final BusinessRepository businesses;private final TenantTableNameResolver tables;private final JdbcTemplate jdbc;private final AuditService audit;
 public StoreAssetController(BusinessRepository businesses,TenantTableNameResolver tables,JdbcTemplate jdbc,AuditService audit){this.businesses=businesses;this.tables=tables;this.jdbc=jdbc;this.audit=audit;}
 public record AssetResponse(UUID id,String url,String contentType,long sizeBytes){}
 @PostMapping(value="/api/tenant/assets",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional public AssetResponse upload(@RequestParam String assetType,@RequestParam("file") MultipartFile file,Authentication auth){TokenService.TokenPrincipal principal=(TokenService.TokenPrincipal)auth.getDetails();UUID businessId=principal.businessId();if(businessId==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Tenant context required.");if(!List.of("PRODUCT_IMAGE","STORE_LOGO").contains(assetType))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported asset type.");if(file.isEmpty()||file.getSize()>MAX)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Images must be no larger than 5 MB.");String mime=file.getContentType()==null?"":file.getContentType().toLowerCase(Locale.ROOT);if(!List.of("image/jpeg","image/png").contains(mime))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only JPEG and PNG images are supported.");try{byte[] bytes=file.getBytes();var image=ImageIO.read(new ByteArrayInputStream(bytes));if(image==null||image.getWidth()<1||image.getHeight()<1||image.getWidth()>6000||image.getHeight()>6000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The file is not a valid image or its dimensions are too large.");String prefix=tables.prefix(businessId).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Tenant tables are not provisioned."));UUID id=UUID.randomUUID();String table=tables.table(prefix,"store_assets");String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));jdbc.update("INSERT INTO "+table+"(id,asset_type,mime_type,bytes,sha256_hex) VALUES(?,?,?,?,?)",id,assetType,mime,bytes,hash);Business b=businesses.findById(businessId).orElseThrow();String url="/api/store/"+b.getSlug()+"/assets/"+id;if("STORE_LOGO".equals(assetType)){b.setLogoAssetId(id);jdbc.update("UPDATE "+tables.table(prefix,"store_settings")+" SET logo_asset_id=? WHERE id=1",id);}audit.record(auth.getName(),principal.role(),businessId,"STORE_ASSET_UPLOADED","STORE_ASSET",id.toString(),"SUCCESS","{\"type\":\""+assetType+"\"}");return new AssetResponse(id,url,mime,bytes.length);}catch(IOException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Could not read image.");}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Image could not be stored.");}}
 @GetMapping("/api/store/{slug}/assets/{id}") public ResponseEntity<byte[]> publicAsset(@PathVariable String slug,@PathVariable UUID id){Business b=businesses.findBySlugIgnoreCase(slug).filter(Business::isOperational).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Store not found."));String prefix=tables.prefix(b.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Asset not found."));List<Map<String,Object>> rows=jdbc.queryForList("SELECT mime_type,bytes FROM "+tables.table(prefix,"store_assets")+" WHERE id=? AND asset_type IN ('PRODUCT_IMAGE','STORE_LOGO')",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Asset not found.");Map<String,Object> row=rows.get(0);String mime=(String)row.get("mime_type");byte[] bytes=(byte[])row.get("bytes");return ResponseEntity.ok().contentType(MediaType.parseMediaType(mime)).cacheControl(CacheControl.maxAge(java.time.Duration.ofHours(1)).cachePublic()).header("X-Content-Type-Options","nosniff").body(bytes);}
}
